import ast, sys, os, re, hashlib, collections
files=[os.path.join(d,f) for r in ('.claude','tools') for d,_,fs in os.walk(r) for f in fs if f.endswith('.py') and not f.startswith('test_') and f!='conftest.py']
allf=[os.path.join(d,f) for r in ('.claude','tools') for d,_,fs in os.walk(r) for f in fs if f.endswith('.py')]
src={f:open(f,encoding='utf-8').read() for f in allf}
trees={f:ast.parse(src[f]) for f in allf}
# lengths
print('files>900:',[ (f,len(src[f].splitlines())) for f in files if len(src[f].splitlines())>900])
fl=[]
for f in files:
    for n in ast.walk(trees[f]):
        if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)):
            fl.append((n.end_lineno-n.lineno+1,f,n.name,n.lineno))
fl.sort(reverse=True); print('func>100:',[x for x in fl if x[0]>100]); print('top5',fl[:5])
# top-level defs not read elsewhere
names=collections.defaultdict(list)
for f in files:
    for n in trees[f].body:
        if isinstance(n,(ast.FunctionDef,ast.ClassDef)): names[n.name].append((f,n.lineno))
        elif isinstance(n,ast.Assign):
            for t in n.targets:
                if isinstance(t,ast.Name): names[t.id].append((f,n.lineno))
use=collections.Counter()
for f in files:
    for n in ast.walk(trees[f]):
        if isinstance(n,ast.Name) and isinstance(n.ctx,ast.Load): use[n.id]+=1
        elif isinstance(n,ast.Attribute): use[n.attr]+=1
        elif isinstance(n,ast.alias): use[n.name.split('.')[-1]]+=1
# string uses (argparse dispatch via getattr etc.)
alltxt='\n'.join(src.values())
for nm,locs in sorted(names.items()):
    if nm.startswith('__') or nm=='main': continue
    if use[nm]==0:
        cnt=len(re.findall(r'\b'+re.escape(nm)+r'\b',alltxt))
        print('unread:',nm,locs,'textcount',cnt)
# same-name funcs in different modules
fn=collections.defaultdict(list)
for f in files:
    for n in trees[f].body:
        if isinstance(n,ast.FunctionDef): fn[n.name].append(f)
for k,v in fn.items():
    if len(v)>1 and not k.startswith('__') and k!='main': print('samename:',k,v)
# duplicate bodies >=6 lines
h=collections.defaultdict(list)
for f in files:
    for n in ast.walk(trees[f]):
        if isinstance(n,ast.FunctionDef) and n.end_lineno-n.lineno+1>=6:
            body=ast.dump(ast.Module(body=n.body,type_ignores=[]))
            h[hashlib.md5(body.encode()).hexdigest()].append((f,n.name,n.lineno))
for k,v in h.items():
    if len(v)>1: print('dupbody:',v)
# windows of 8 identical lines across files
W=8; win=collections.defaultdict(set)
for f in files:
    ls=[l.strip() for l in src[f].splitlines()]
    for i in range(len(ls)-W):
        w=ls[i:i+W]
        if sum(1 for x in w if len(x)>3)>=W-1 and not all(x.startswith(('import','from','#')) for x in w):
            win[tuple(w)].add((f,i+1))
for w,s in win.items():
    if len({f for f,_ in s})>1: print('win8:',sorted(s))
EOF
